      function queueParse(){state.parseGeneration++;clearTimeout(state.parseTimer);clearTimeout(state.apiTimer);state.parseTimer=setTimeout(()=>parsePreview($('#memoInput').value),380)}
      function setCaptureMode(mode){if(state.captureMode===mode)return;cancelAutoAdd();state.parseGeneration++;clearTimeout(state.parseTimer);clearTimeout(state.apiTimer);state.captureMode=mode;const task=mode==='task';$('#scheduleMode').classList.toggle('active',!task);$('#taskMode').classList.toggle('active',task);$('#scheduleMode').setAttribute('aria-pressed',String(!task));$('#taskMode').setAttribute('aria-pressed',String(task));$('#memoInput').placeholder=task?'例：明日 クリーニングを受け取る\n10月20日 18時までに申込書を提出':'例：明日 14時から歯医者\n来週の火曜 10時 セミナー 1時間半';$('#memoInput').setAttribute('aria-label',task?'タスクをメモ':'予定をメモ');$('#captureTip').innerHTML=task?'日付の指定が必要です。<br>時刻は省略できます。':'日付を省略すると今日になります。<br>開始時刻がない予定は追加されません。';$('#parseModeLabel').textContent=task?'タスクの日付を入力':'時刻を含めて入力';$('#addButton').innerHTML='__ICON_PLUS__<span>'+(task?'タスクを追加':'予定を追加')+'</span>';$('#preview').classList.remove('show');state.preview=null;state.previewText='';if($('#memoInput').value.trim()){queueParse();scheduleAutoAdd()}}
       async function createEvent(){const parsed=state.preview;if(!parsed)return;cancelAutoAdd();state.parseGeneration++;clearTimeout(state.parseTimer);clearTimeout(state.apiTimer);const task=parsed.type==='task',button=$('#addButton');button.disabled=true;button.innerHTML='__ICON_CHECK__<span>追加中…</span>';const localEvent=normalizeEvent({...parsed,id:id()});let saved=localEvent,cloud=false,syncResult=null,cloudError=false;const autoSync=!task&&!!(state.prefs.autoSync&&state.status.google.connected);if(state.status.mode==='cloud'&&state.status.authenticated){const response=await api('/api/events',{method:'POST',body:JSON.stringify({event:serializeEvent(parsed),autoSync})});if(response.ok&&response.data.event){saved=normalizeEvent({...response.data.event,cloudStored:true});cloud=true;syncResult=response.data.sync||null;state.cloudUnavailable=false}else{cloudError=true;state.cloudUnavailable=true}}if(autoSync)saved.syncStatus=syncResult&&syncResult.status||'failed';if(syncResult&&syncResult.status==='failed')saved.syncError=syncResult.message||syncResult.errors||'Google Calendarとの同期に失敗しました。';state.events.push(saved);state.remote=state.events.some(e=>e.cloudStored);saveLocal();$('#memoInput').value='';state.preview=null;$('#preview').classList.remove('show');$('#parseModeLabel').textContent=state.captureMode==='task'?'タスクの日付を入力':'時刻を含めて入力';button.innerHTML='__ICON_PLUS__<span>'+(state.captureMode==='task'?'タスクを追加':'予定を追加')+'</span>';button.disabled=true;render();$('#memoInput').focus();if(cloudError)toast(task?'タスクをこの端末に保存しました。クラウドに保存できませんでした。':autoSync?'予定をこの端末に保存しました。Google Calendarには反映できていません。':'クラウドに保存できず、この端末に予定を保存しました。');else if(autoSync){if(syncResult&&syncResult.status==='synced')toast('予定をGoogle Calendarに反映しました');else toast('予定をクラウドに保存しました。Google Calendarにはまだ反映できていません。')}else toast(task?(cloud?'タスクをアカウントに保存しました':'タスクをこの端末に保存しました'):(cloud?'予定をアカウントに保存しました':'この端末に予定を保存しました'))}
      function localInputValue(instant){const d=new Date(instant),p=n=>String(n).padStart(2,'0');return d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate())+'T'+p(d.getHours())+':'+p(d.getMinutes())}
