      function openTaskEdit(event){const body=$('#modalBody'),title=$('#modalTitle');title.textContent='タスクを編集';body.innerHTML='<form id="taskEditForm" class="task-edit-form"><label>タスク名<input id="taskEditTitle" required maxlength="160" value="'+escapeHtml(event.title)+'"></label><label>期限日<input id="taskEditDate" type="date" required value="'+escapeHtml(event.dueDate||new Date(event.start).toLocaleDateString('sv-SE'))+'"></label><label>期限時刻（任意）<input id="taskEditTime" type="time" value="'+escapeHtml(event.dueTime||'')+'"></label><p id="taskEditError" class="form-error" aria-live="polite"></p><div class="modal-actions"><button type="button" class="modal-secondary" id="taskEditCancel">キャンセル</button><button type="submit" class="modal-primary">保存</button></div></form>';$('#taskEditCancel').onclick=closeModal;$('#taskEditForm').onsubmit=e=>{e.preventDefault();const name=$('#taskEditTitle').value.trim(),dateValue=$('#taskEditDate').value,timeValue=$('#taskEditTime').value||null,m=dateValue.match(/^(\d{4})-(\d{2})-(\d{2})$/);if(!name||!m){$('#taskEditError').textContent='タスク名と日付を確認してください。';return}const [year,month,day]=m.slice(1).map(Number),check=new Date(year,month-1,day);if(check.getFullYear()!==year||check.getMonth()!==month-1||check.getDate()!==day){$('#taskEditError').textContent='存在する日付を入力してください。';return}if(timeValue&&!/^(?:[01]\d|2[0-3]):[0-5]\d$/.test(timeValue)){$('#taskEditError').textContent='期限時刻を確認してください。';return}const [hour,minute]=(timeValue||'12:00').split(':').map(Number),start=new Date(year,month-1,day,hour,minute);persistEdit({...event,type:'task',title:name,dueDate:dateValue,dueTime:timeValue,start:start.toISOString(),end:new Date(start.getTime()+(timeValue?5:1)*60000).toISOString(),recurrence:null,completed:event.completed})};$('#modalBackdrop').classList.add('show');$('#modalBackdrop').setAttribute('aria-hidden','false');setTimeout(()=>$('#taskEditTitle').focus(),50)}
       async function persistEdit(updated){const index=state.events.findIndex(e=>e.id===updated.id);if(index<0)return;const old=state.events[index],itemName=updated.type==='task'?'タスク':'予定';if(old.cloudStored){const response=await api('/api/events/'+encodeURIComponent(old.id),{method:'PUT',body:JSON.stringify({event:serializeEvent(updated),autoSync:updated.type!=='task'&&!!(state.prefs.autoSync&&state.status.google.connected)})});if(!response.ok||!response.data.event){toast(response.status===401?'アカウントに接続し直してください。':itemName+'をクラウドで更新できませんでした。変更は保存されていません。');return}updated=normalizeEvent({...response.data.event,cloudStored:true});if(response.data.sync&&response.data.sync.status==='failed'){updated.syncStatus='failed';updated.syncError=response.data.sync.message||'Google Calendarとの同期に失敗しました。'}}state.events[index]=updated;state.googleOverrides=state.googleOverrides.filter(item=>item.id!==updated.id);saveLocal();render();closeModal();if(state.status.google.connected)loadGoogleEvents();toast(updated.syncStatus==='failed'?'予定は更新しましたが、Google同期に失敗しました。':itemName+'を更新しました')}
